        dy = pa[1] - pb[1]
        return (dx * dx + dy * dy) ** 0.5

    coords = fetch(instance, ("coords", "coordinates", "locations", "pos", "positions"), None)
    demands = fetch(instance, ("demands", "demand"), None)
    capacity = fetch(instance, ("capacity", "vehicle_capacity"), None)
    depot_id = fetch(instance, ("depot", "depot_id"), 0)

    demand_of = {}
    coord_of = {}
    customer_ids = []

    if isinstance(demands, dict):
        for k in demands:
            if k != depot_id:
                customer_ids.append(k)
                demand_of[k] = demands[k]
    elif demands is not None:
        dlist = to_list(demands)
        start = 1 if depot_id == 0 and len(dlist) > 0 else 0
        for i in range(start, len(dlist)):
            customer_ids.append(i)
            demand_of[i] = dlist[i]
    else:
        customers = fetch(instance, ("customers", "nodes"), [])
        customer_ids = [c for c in to_list(customers) if c != depot_id]
        for c in customer_ids:
            demand_of[c] = 0

    if isinstance(coords, dict):
        for k in coords:
            coord_of[k] = coords[k]
            if k != depot_id and k not in customer_ids:
                customer_ids.append(k)
    elif coords is not None:
        clist = to_list(coords)
        start = 1 if depot_id == 0 and len(clist) > 0 else 0
        for i in range(start, len(clist)):
            coord_of[i] = clist[i]
            if i not in customer_ids:
                customer_ids.append(i)

    customer_ids = sorted(set(customer_ids), key=lambda x: x)

    total_demand = 0
    for c in customer_ids:
        try:
            total_demand += float(demand_of.get(c, 0))
        except Exception:
            pass
    if capacity is None:
        capacity = total_demand if total_demand > 0 else 1
    try:
        capacity = float(capacity)
    except Exception:
        capacity = total_demand if total_demand > 0 else 1

    depot_coord = coord_of.get(depot_id, None)

    def route_load(route):
        s = 0.0
        for c in route:
            try:
                s += float(demand_of.get(c, 0))
            except Exception:
                pass
        return s

    def route_cost(route):
        prev = depot_coord
        cst = 0.0
        for c in route:
            cst += dist(prev, coord_of.get(c, None))
            prev = coord_of.get(c, None)
        cst += dist(prev, depot_coord)
        return cst

    def route_key(route):
        return tuple(route)

    if not customer_ids:
        return []

    # Initial solution: greedy nearest-feasible insertion into existing routes.
    routes = []
    unassigned = customer_ids[:]
    unassigned.sort(key=lambda c: (0 if coord_of.get(c, None) is not None else 1, c))

    while unassigned:
        c = unassigned.pop(0)
        placed = False
        best_r = None
        best_k = None
        best_delta = None
        for r_idx, r in enumerate(routes):
            if route_load(r) + float(demand_of.get(c, 0)) > capacity + 1e-12:
                continue
            base = route_cost(r)
            for k in range(len(r) + 1):
                cand = r[:k] + [c] + r[k:]
                delta = route_cost(cand) - base
                if best_delta is None or delta < best_delta or (delta == best_delta and (r_idx, k) < (best_r, best_k)):
                    best_delta = delta
                    best_r = r_idx
                    best_k = k
        if best_r is not None:
            r = routes[best_r]
            routes[best_r] = r[:best_k] + [c] + r[best_k:]
            placed = True
        if not placed:
            routes.append([c])

    # Clarke-Wright style merges
    savings = []
    if depot_coord is not None:
        for i in range(len(customer_ids)):
            a = customer_ids[i]
            da = dist(depot_coord, coord_of.get(a, None))
            for j in range(i + 1, len(customer_ids)):
                b = customer_ids[j]
                db = dist(depot_coord, coord_of.get(b, None))
                dab = dist(coord_of.get(a, None), coord_of.get(b, None))
                savings.append((da + db - dab, a, b))
        savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    def pos_map(rs):
        m = {}
        for idx in range(len(rs)):
            for c in rs[idx]:
                m[c] = idx
        return m

    if savings:
        merged = True
        while merged:
            merged = False
            pm = pos_map(routes)
            for _, i, j in savings:
                ri = pm.get(i, None)
                rj = pm.get(j, None)
                if ri is None or rj is None or ri == rj:
                    continue
                a = routes[ri]
                b = routes[rj]
                if i not in (a[0], a[-1]) or j not in (b[0], b[-1]):
                    continue
                candidates = []
                if a[-1] == i and b[0] == j:
                    candidates.append(a + b)
                if a[0] == i and b[-1] == j:
                    candidates.append(b + a)
                if a[0] == i and b[0] == j:
                    candidates.append(list(reversed(a)) + b)
                if a[-1] == i and b[-1] == j:
                    candidates.append(a + list(reversed(b)))
                best = None
                for cand in candidates:
                    if route_load(cand) <= capacity + 1e-12:
                        best = cand
                        break
                if best is None:
                    continue
                if ri > rj:
                    ri, rj = rj, ri
                routes[ri] = best
                routes.pop(rj)
                merged = True
                break

    # Relocate improvement
    improved = True
    while improved:
        improved = False
        routes = [r for r in routes if r]
        for i in range(len(routes)):
            if improved:
                break
            ra = routes[i]
            base_a = route_cost(ra)
            for p in range(len(ra)):
                c = ra[p]
                dc = float(demand_of.get(c, 0))
                ra2 = ra[:p] + ra[p + 1:]
                cost_ra2 = route_cost(ra2) if ra2 else 0.0
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rb = routes[j]
                    if route_load(rb) + dc > capacity + 1e-12:
                        continue
                    base_b = route_cost(rb)
                    best_k = None
                    best_delta = None
                    for k in range(len(rb) + 1):
                        cand = rb[:k] + [c] + rb[k:]
                        delta = cost_ra2 + route_cost(cand) - base_a - base_b
                        if best_delta is None or delta < best_delta or (delta == best_delta and k < best_k):
                            best_delta = delta
                            best_k = k
                    if best_delta is not None and best_delta < -1e-12:
                        routes[i] = ra2
                        routes[j] = rb[:best_k] + [c] + rb[best_k:]
                        improved = True
                        break
                if improved:
                    break

    # Final cleanup and deterministic ordering
    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (r[0], len(r), route_key(r)))
    return routes
